// Package earley is the query parser of the programs generated by
// elanc-go (S7d task 5): a port of the Earley parser of REM's compiled
// programs (src/compiler/earley: lexer lstream.cc and ichstream.cc,
// parser earley.cc and grammar.cc, tables runtimeInit.cc, semantic
// actions esemact), function by function, so that the queries accepted,
// the resolution of ambiguities (priorities, associativity) and the error
// messages are REM's. The C names are given in the comments.
//
// The parser is driven by the grammar rules of the program ([Tables]), as
// REM's by its gram[] table; the term is built from the derivation by
// [Build], as REM's computeTerm (src/compiler/runtime/termIn.c). The
// package does not depend on elanrt: the identifiers and the terms are
// given by the caller.
//
// Departures from REM, where it reads outside its arrays (see the S7d
// plan, Task 5 rulings): at the end of the input before a complete term,
// the error is reported there (REM advances its completed situations past
// the end of their rules); a string lexem prints as STRING or as the
// string in double quotes (REM prints a pointer read past its table of
// identifiers, "(null)" on macOS).
package earley

import (
	"bufio"
	"io"
	"strconv"
)

// Lexem is a lexem in REM's encoding (class lexem, commondefs.h): the
// order of the lexems (operator >) orders the lists of the parser, hence
// the list of the expected lexems of an error message. A number is its
// value (an unsigned 32-bit number: REM's int wraps above 2^31-1 and then
// stops being a number lexem; here it stays one).
type Lexem int64

// The ranges of lexems (commondefs.h).
const (
	NoLexem      Lexem = -256 // NOLEXEM: end of a rule, end of the input
	BlankLexem   Lexem = -257 // BLANKLEXEM
	IdentLexem   Lexem = -259 // IDENT: any identifier (standard rule)
	BofIdent     Lexem = -260 // BOFIDENT: identifier n is BOFIDENT-n
	MaxNofIdent        = 3000 // MAXNOFIDENT
	MaxNofString       = 10000
	StringLexem  Lexem = BofIdent - MaxNofIdent     // STRING: any string
	BofString    Lexem = BofIdent - MaxNofIdent - 1 // string i is BOFSTRING-i
	JustNumber   Lexem = BofString - MaxNofString   // JUSTNUMBER: any number
	BofTypes     Lexem = JustNumber - 1             // sort n is BOFTYPES-n
)

// IdentLex is the lexem of identifier n (cridlex(n)).
func IdentLex(n int32) Lexem { return BofIdent - Lexem(n) }

// TypeLex is the lexem of sort n (crtypelex).
func TypeLex(n int32) Lexem { return BofTypes - Lexem(n) }

// CharLex is the lexem of the character c (crcharlex).
func CharLex(c int32) Lexem { return -Lexem(c) }

// NumLex is the lexem of the number n (crnumlex).
func NumLex(n uint32) Lexem { return Lexem(n) }

func (l Lexem) terminal() bool      { return l > BofTypes }
func (l Lexem) nonterminal() bool   { return l <= BofTypes }
func (l Lexem) isEndOfStream() bool { return l == NoLexem }
func (l Lexem) isBlank() bool       { return l == BlankLexem }
func (l Lexem) isRealID() bool      { return l <= BofIdent && l > BofIdent-MaxNofIdent }
func (l Lexem) isRealString() bool  { return l <= BofString && l > BofString-MaxNofString }
func (l Lexem) isRealNum() bool     { return l >= 0 }
func (l Lexem) idval() int32        { return int32(BofIdent - l) }
func (l Lexem) typeval() int32      { return int32(BofTypes - l) }
func (l Lexem) numval() int32       { return int32(uint32(l)) }

// ichstream is a stream of characters with its position (ichstream.cc).
type ichstream struct {
	r         *bufio.Reader
	fchar     int // the next character (EOF: -1)
	name      string
	line, pos int
}

const eof = -1

func newIchstream(r io.Reader, name string) *ichstream {
	s := &ichstream{r: bufio.NewReader(r), fchar: 1, name: name}
	// commonopen
	var c int
	s.ich(&c)
	return s
}

// ich gives the next character and reads the one after it.
func (s *ichstream) ich(c *int) {
	*c = s.fchar
	if *c != eof {
		b, err := s.r.ReadByte()
		if err != nil {
			s.fchar = eof
		} else {
			s.fchar = int(b)
		}
		if s.fchar == '\n' {
			s.line++
			s.pos = 0
		} else {
			s.pos++
		}
	}
}

// fuch gives the next character, which stays in the stream.
func (s *ichstream) fuch(c *int) { *c = s.fchar }

func (s *ichstream) blankskip() {
	var c int
	for s.fchar <= ' ' && s.fchar != eof {
		s.ich(&c)
	}
}

// Fatal is an error that stops the program: Msg is written on stderr and
// the program exits with Status (REM's failexit: 1).
type Fatal struct {
	Msg    string
	Status int
}

func (e *Fatal) Error() string { return e.Msg }

// lstream is the stream of lexems of the parser (lstream.cc), with one
// lexem of lookahead (flex).
type lstream struct {
	flex Lexem
	istr *ichstream
	t    *Tables
	// strings are the string constants read (stringconstants)
	strings []string
	inline  bool // lastinline != NULL
	// stderr gets the warnings (sterr)
	stderr io.Writer
}

// identifier length limit (IDLEN) and string constant limit (STRLEN)
const (
	idLen  = 50
	strLen = 1000
)

func newLstream(s *ichstream, t *Tables, stderr io.Writer) *lstream {
	f := &lstream{istr: s, t: t, stderr: stderr}
	f.ilex(&f.flex)
	return f
}

// fulex gives the next lexem, which stays in the stream.
func (f *lstream) fulex(l *Lexem) { *l = f.flex }

func isalpha(c int) bool { return 'a' <= c && c <= 'z' || 'A' <= c && c <= 'Z' }
func isdigit(c int) bool { return '0' <= c && c <= '9' }

// ilex gives the next lexem and reads the one after it (a lexical error
// panics with a *Fatal).
func (f *lstream) ilex(l *Lexem) {
	var c, fc, tc int
	*l = f.flex
	f.istr.blankskip()
	f.istr.ich(&c)
	f.istr.fuch(&fc)
	// comments and inlines
	for c == '/' && (fc == '*' || fc == '/' || fc == '#') {
		switch fc {
		case '/':
			for fc != '\n' {
				f.istr.ich(&c)
				f.istr.fuch(&fc)
				if fc == eof {
					f.fail("[lexan] comment throw end of input stream\n")
				}
			}
		case '#':
			if f.inline {
				f.owarn("\ttwo succesives inline definitions,\n\tprevious one will be lost\n")
			}
			f.inline = true
			f.istr.ich(&c)
			f.istr.ich(&c)
			f.istr.fuch(&fc)
			for c != '#' || fc != '/' {
				f.istr.ich(&c)
				f.istr.fuch(&fc)
				if fc == eof {
					f.fail("[lexan] inline throw end of input stream\n")
				}
			}
		default:
			f.istr.ich(&c)
			f.istr.ich(&c)
			f.istr.fuch(&fc)
			for c != '*' || fc != '/' {
				f.istr.ich(&c)
				f.istr.fuch(&fc)
				if fc == eof {
					f.fail("[lexan] comment throw end of input stream\n")
				}
			}
		}
		f.istr.ich(&c)
		f.istr.blankskip()
		f.istr.ich(&c)
		f.istr.fuch(&fc)
	}
	if c == '"' {
		var b []byte
		f.istr.ich(&c)
		f.istr.fuch(&fc)
		for c != '"' {
			switch {
			case c == '\\' && fc == 'n':
				b = append(b, '\n')
				f.istr.ich(&c)
				f.istr.fuch(&fc)
			case c == '\\' && fc == 't':
				b = append(b, '\t')
				f.istr.ich(&c)
				f.istr.fuch(&fc)
			case c == '\\' && fc == '\\':
				b = append(b, '\\')
				f.istr.ich(&c)
				f.istr.fuch(&fc)
			case c == '\\' && fc == '"':
				b = append(b, '"')
				f.istr.ich(&c)
				f.istr.fuch(&fc)
			default:
				b = append(b, byte(c))
			}
			if len(b) >= strLen {
				panic(&Fatal{Msg: "\nstring constant too long\n", Status: 1})
			}
			f.istr.ich(&c)
			f.istr.fuch(&fc)
		}
		// (mstrdup: a C string stops at a NUL byte)
		for i, x := range b {
			if x == 0 {
				b = b[:i]
				break
			}
		}
		f.flex = f.crstringlex(string(b))
		return
	}
	if c == '`' {
		var n int
		f.istr.ich(&c)
		f.istr.fuch(&fc)
		switch {
		case c == '\\' && fc == 'n':
			f.istr.ich(&c)
			f.istr.fuch(&fc)
			n = '\n'
		case c == '\\' && fc == 't':
			f.istr.ich(&c)
			f.istr.fuch(&fc)
			n = '\t'
		case c == '\\' && fc == '\\':
			f.istr.ich(&c)
			f.istr.fuch(&fc)
			n = '\\'
		case c == '\\' && fc == '"':
			f.istr.ich(&c)
			f.istr.fuch(&fc)
			n = '"'
		default:
			n = c
		}
		f.istr.ich(&c)
		f.istr.fuch(&fc)
		if c != '`' {
			panic(&Fatal{Msg: "\nwrong string constant\n", Status: 1})
		}
		f.flex = NumLex(uint32(int32(n)))
		return
	}
	// BORO's hacks
	if c == '\\' {
		if fc == 'n' {
			f.istr.ich(&c)
			f.flex = IdentLex(f.t.IdentIndex("\n"))
			return
		}
		if fc == 't' {
			f.istr.ich(&c)
			f.flex = IdentLex(f.t.IdentIndex("\t"))
			return
		}
	}
	// identifier
	if isalpha(c) {
		ide := make([]byte, 0, idLen)
		ide = append(ide, byte(c))
		for isalpha(fc) || isdigit(fc) || fc == '_' {
			f.istr.ich(&tc)
			// (ide[i>=(IDLEN-1)?(IDLEN-1):i++]=tc, then ide[i]=0: the
			// first IDLEN-1 characters)
			if len(ide) < idLen-1 {
				ide = append(ide, byte(tc))
			}
			f.istr.fuch(&fc)
		}
		f.flex = IdentLex(f.t.IdentIndex(string(ide)))
		return
	}
	// number: modulo 2^32
	if isdigit(c) {
		u := uint32(c - '0')
		for isdigit(fc) {
			f.istr.ich(&c)
			f.istr.fuch(&fc)
			u = u*10 + uint32(c-'0')
		}
		f.flex = NumLex(u)
		return
	}
	if c == eof {
		f.flex = NoLexem
		return
	}
	f.flex = CharLex(int32(c))
}

// crstringlex is the lexem of a new string constant.
func (f *lstream) crstringlex(s string) Lexem {
	if len(f.strings) >= MaxNofString {
		panic(&Fatal{Msg: "\ntoo many string constants\n", Status: 1})
	}
	f.strings = append(f.strings, s)
	return BofString - Lexem(len(f.strings)-1)
}

// stringval is the string of a string lexem.
func (f *lstream) stringval(l Lexem) string { return f.strings[BofString-l] }

// position is oerr's line: "\n[error] :file=NAME\tline=L\tpos=P\n".
func (f *lstream) position(kind string) string {
	return "\n[" + kind + "] :file=" + f.istr.name + "\tline=" + strconv.Itoa(f.istr.line) +
		"\tpos=" + strconv.Itoa(f.istr.pos) + "\n"
}

// fail is oerr(msg) then failexit.
func (f *lstream) fail(msg string) {
	panic(&Fatal{Msg: f.position("error") + msg, Status: 1})
}

// owarn(msg) (warnings is always on in REM's runtime).
func (f *lstream) owarn(msg string) {
	io.WriteString(f.stderr, f.position("warning")+msg)
}

// alfsy is the text of a lexem (lexem::alfsy).
func (f *lstream) alfsy(l Lexem) string {
	switch {
	case l.nonterminal():
		return "sort(" + strconv.Itoa(int(l.typeval())) + ")"
	case l == BlankLexem:
		return "BLANKLEXEM"
	case l == NoLexem:
		return "ENDOFLSTREAM"
	case l == IdentLexem:
		return "IDENTIFIER"
	case l == JustNumber:
		return "NUMBER"
	case l >= 0:
		return strconv.FormatUint(uint64(l), 10)
	case l == StringLexem:
		// (REM: tabofident.ide(3000), past its table)
		return "STRING"
	case l.isRealString():
		return strconv.Quote(f.stringval(l))
	case l <= BofIdent:
		return f.t.IdentName(l.idval())
	}
	return string([]byte{byte(-l)})
}

// erralfsy is alfsy, the characters (and numbers) 0 to 32 as '\N'.
func (f *lstream) erralfsy(l Lexem) string {
	if l <= 0 && l >= -32 {
		return "'\\" + strconv.Itoa(int(-l)) + "'"
	}
	return f.alfsy(l)
}
